+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold in those days, actual use from every consume movement, and the
+ * difference (actual - theoretical). Items where both are zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (at) => {
+    const day = new Date(at).toISOString().slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const lines = new Map();
+  const line = (itemId) => {
+    if (!lines.has(itemId)) lines.set(itemId, { theoretical: 0, actual: 0 });
+    return lines.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const n of saleUses(store, s.dishId, s.qty)) line(n.itemId).theoretical += n.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) line(batch.itemId).actual += m.qty;
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...lines]
+    .map(([itemId, l]) => {
+      const item = getItem(store, itemId);
+      const theoretical = r3(l.theoretical);
+      const actual = r3(l.actual);
+      return { itemId, name: item.name, unit: item.unit, theoretical, actual, difference: r3(actual - theoretical) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
