@@ -0,0 +1,42 @@
+// Sales from the till: each dish sold uses one portion of its recipe per
+// unit of `qty`. A ticket is booked once; booking it again does nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a ticket has already been booked. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities one sale line uses: one recipe portion per `qty`. */
+export function saleUses(store, dishId, qty) {
+  const dish = getDish(store, dishId);
+  return scaled(getRecipe(store, dish.recipeId), qty).filter((n) => n.qty > 0);
+}
+
+/**
+ * Books the lines of new tickets ({ ticket, soldAt, dishId, qty }): consumes
+ * the ingredients with ref `sale:<ticket>` at `soldAt` and stores each line.
+ * All or nothing: on any error the store is left as it was and the error
+ * carries the index of the failing line in `lineIndex`.
+ */
+export function bookSales(store, lines) {
+  const saved = structuredClone(store.data);
+  let index = -1;
+  try {
+    store.data.sales ??= [];
+    for (const [i, line] of lines.entries()) {
+      index = i;
+      for (const n of saleUses(store, line.dishId, line.qty))
+        consume(store, n.itemId, n.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+      store.data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty });
+    }
+  } catch (e) {
+    store.data = saved;
+    if (e instanceof AppError) e.lineIndex = index;
+    throw e;
+  }
+  return store.data.sales.slice(-lines.length);
+}
